Translate("frFR", "razorfen-downs", {
	title = "Souilles de Tranchebauge",
	aliases = { "les Souilles" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Souilles de Tranchebauge sont un vaste dédale d'épines géantes à la lisière sud des {link:the-barrens}Tarides{/link}, là où les plaines descendent vers {link:thousand-needles}Mille pointes{/link}. Les {link:quilboar}hurans{/link} le tiennent pour le plus sacré de tous leurs lieux. Son entrée est une caverne dans les épines qui a la forme de la gueule ouverte d'un grand sanglier. Sous le dôme d'épines se trouvent les lieux de sépulture de leur peuple et le siège de leurs grands prêtres. Aujourd'hui, les morts des Souilles ne reposent plus. Le {link:scourge}Fléau{/link} est venu en {link:kalimdor}Kalimdor{/link}, et il a fait du dédale sacré une place forte des morts.]=],
		},
		{
			title = "Origines",
			text = [=[Les hurans disent que le demi-dieu Agamaggan tomba dans les {link:the-barrens}Tarides{/link} il y a bien longtemps, et que des épines poussèrent partout où son sang toucha la terre. Le plus grand de ces fourrés est Tranchebauge, qu'ils croient être son corps même. Les Souilles et le {link:razorfen-kraul}Kraal de Tranchebauge{/link} s'élevèrent des mêmes lianes puissantes. Le mystique {link:mangletooth}Mangletooth{/link}, tenu en cage, dit que les Souilles sont le lieu le plus saint de tous, car leur entrée est la gueule même d'Agamaggan, qui avale ceux qui ne lui sont pas fidèles. Aucune chronique ne dit quand les hurans s'installèrent ici pour la première fois.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Une liche appelée {link:amnennar-the-coldbringer}Amnennar le Porte-froid{/link} règne sur les Souilles. Les grands prêtres des hurans, la {link:death-s-head}Tête de mort{/link}, se sont liés à lui, et beaucoup de ceux de leur tribu marchent désormais comme des morts-vivants desséchés. Des squelettes défilent dans les tunnels et une grande abomination se gave de cadavres. Les hurans traînent ici des captifs venus de tout le territoire des {link:the-barrens}Tarides{/link}. Près de l'entrée se dresse une idole où ces captifs sont brûlés et dévorés.

La nouvelle s'est répandue. Un émissaire du {link:scourge}Fléau{/link}, l'ambassadeur {link:ambassador-malcin}Malcin{/link}, attend devant la porte et a écrit à la vieille qui règne sur {link:razorfen-kraul}le Kraal{/link}. L'{link:night-elves}elfe de la nuit{/link} {link:myriam-moonsinger}Myriam Moonsinger{/link} surveille le dédale depuis une colline au sud. À {link:undercity}Undercity{/link}, {link:varimathras}Varimathras{/link} a appris l'existence de l'émissaire, et à {link:stormwind-city}Stormwind{/link}, l'{link:archbishop-benedictus}archevêque Benedictus{/link} a entendu parler de la liche. Tous deux veulent qu'il soit détruit.]=],
		},
		{
			title = "Dans les Souilles",
			text = [=[• {b}La Porte.{/b} L'arche en gueule de sanglier s'ouvre dans les épines, à la lisière sud des {link:the-barrens}Tarides{/link}. Des cultistes de la {link:death-s-head}Tête de mort{/link} et des guerriers hurans se rassemblent autour.
• {b}Les Enclos.{/b} Près de l'entrée, les hurans gardent leurs prisonniers. Parmi eux se trouvent un cuisinier de {link:stormwind-city}Stormwind{/link} nommé {link:henry-stern}Henry Stern{/link} et un inconnu qui se fait appeler {link:belnistrasz}Belnistrasz{/link}.
• {b}L'Idole.{/b} Une grande idole près de la porte sert de four aux hurans pour leurs captifs.
• {b}La Salle du gong.{/b} Un grand gong pend dans une salle couverte de toiles. Quelque chose d'aveugle et d'affamé attend au-delà, à l'écoute.
• {b}Le Tas d'ossements.{/b} Un chaman mort, {link:mordresh-fire-eye}Mordresh Fire Eye{/link}, danse sur un monticule de crânes parmi ses frères squelettes.
• {b}La Spirale d'épines.{/b} Une montagne de lianes s'enroule jusqu'au sommet où {link:amnennar-the-coldbringer}le Porte-froid{/link} tient sa cour. {link:glutton}Glutton{/link} avance lourdement sur ses sentiers inférieurs.]=],
		},
	},
})

Translate("frFR", "belnistrasz", {
	title = "Belnistrasz",
	subtitle = "Le captif des Souilles",
	found = [=[Les enclos des prisonniers, près de l'entrée des Souilles de Tranchebauge]=],
	hint = [=[Libérez l'inconnu retenu captif dans les enclos des Souilles de Tranchebauge.]=],
	allegiance = "Aucune déclarée",
	sections = {
		{
			title = "Résumé",
			text = [=[Belnistrasz est un prisonnier des hurans, que l'on trouve dans leurs enclos près de la porte des {link:razorfen-downs}Souilles de Tranchebauge{/link}. Il a l'apparence d'un homme, et il parle avec le courage tranquille d'un soldat. Il s'était déjà tenu pour mort, ou pour un repas. Il dit sans détour que les hurans ont conclu un marché avec le {link:scourge}Fléau{/link}, et que les Souilles sont le cauchemar qui en est né. Une fois libéré, il ne s'enfuit pas. Il entend porter un coup au mal qui règne ici, pour le bien de tous les peuples.]=],
		},
		{
			title = "Importance",
			text = [=[Belnistrasz se moque des querelles de la {link:horde}Horde{/link} et de l'{link:alliance}Alliance{/link}. Il demande seulement si ceux qui le libèrent se dresseront contre une menace qui pèse sur toutes les races. C'est aussi un étranger, et pas seulement en un sens. Il admet qu'il n'est pas de ces terres, et que chez les siens, un serment prêté sur une pierre est un lien sacré.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il survécut à sa captivité dans les enclos de la {link:death-s-head}Tête de mort{/link}.
• Il offrit à ses sauveurs une pierre de serment en gage de leur cause commune.
• Il entreprit d'éteindre l'idole où les hurans brûlaient leurs captifs.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit sur la façon dont Belnistrasz arriva dans {link:razorfen-downs}les Souilles{/link}, ni sur l'endroit où il partit quand l'idole s'éteignit.]=],
		},
	},
	chapters = {
		{
			title = "La pierre de serment",
			hint = "Jurez d'aider le prisonnier libéré.",
			text = [=[Belnistrasz donna une pierre à ses sauveurs et leur demanda de la lui rendre s'ils voulaient se joindre à lui. Ils le firent. Il ne leur cacha pas le danger. La tâche à venir était rude, dit-il, mais s'ils gardaient l'esprit fixé sur elle, ils pourraient l'emporter.]=],
		},
		{
			title = "L'idole s'éteint",
			hint = [=[Protégez Belnistrasz pendant qu'il accomplit son rituel devant l'idole.]=],
			text = [=[L'idole près de la porte était un four hideux, et Belnistrasz pouvait la sceller à jamais, mais son rituel le laisserait sans défense. Ses compagnons retinrent la {link:death-s-head}Tête de mort{/link} pendant cinq longues minutes tandis qu'il annonçait le temps écoulé. Enfin, les feux s'éteignirent. Belnistrasz avait disparu, et seul un brasero ardent restait là où il s'était tenu. Dans ses flammes apparut un grand dragon rouge aux ailes immenses. Sa voix, plus grave à présent, remercia les mortels qui avaient ranimé sa foi en eux.]=],
		},
	},
	bonds = {
		{ id = "plaguemaw-the-rotting", name = "Plaguemaw le Pourrissant", note = "vint interrompre son rituel" },
		{ id = "henry-stern", name = "Henry Stern", note = "un compagnon de captivité" },
		{ id = "amnennar-the-coldbringer", name = "Amnennar le Porte-froid", note = "l'ennemi de tout ce qu'il défend" },
	},
})

Translate("frFR", "amnennar-the-coldbringer", {
	title = "Amnennar le Porte-froid",
	subtitle = "Liche des Souilles de Tranchebauge",
	found = [=[Le sommet de la Spirale d'épines, au cœur des Souilles de Tranchebauge]=],
	hint = [=[Gravissez la spirale d'épines jusqu'au seigneur des Souilles.]=],
	allegiance = "Fléau · Tête de mort",
	aliases = { "Amnennar", "le Porte-froid" },
	sections = {
		{
			title = "Résumé",
			text = [=[Amnennar le Porte-froid est une liche, un serviteur du roi-liche et le maître des {link:razorfen-downs}Souilles de Tranchebauge{/link}. Il gouverne la {link:death-s-head}Tête de mort{/link} depuis le sommet d'une grande spirale d'épines, parmi des feux froids et des esprits sans repos. On dit que son esprit est si vaste qu'il guide les hurans dans tout ce qu'ils font. Lorsqu'il est menacé, il se proclame la main du roi-liche et appelle à ses côtés les morts gelés.]=],
		},
		{
			title = "Importance",
			text = [=[Amnennar a donné au {link:scourge}Fléau{/link} une place forte en {link:kalimdor}Kalimdor{/link}. Par lui, la peste atteint un peuple qui ne l'avait jamais connue, et la guerre qui mit fin à {link:lordaeron}Lordaeron{/link} traverse la mer. On dit qu'il combattit avec le Fléau lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, et que le roi-liche lui ordonna ensuite de rester en arrière pour répandre sa puissance. Les hurans, chassés de leurs terres, étaient prêts à écouter un seigneur qui leur promettait la maîtrise de la mort.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fit du dédale sacré des hurans un bastion des morts-vivants.
• Il releva les morts des Souilles en squelettes et en guerriers desséchés.
• Il soumit la {link:death-s-head}Tête de mort{/link} à sa volonté.]=],
		},
	},
	chapters = {
		{
			title = "Apporter la Lumière",
			hint = "Répondez à l'appel de l'archevêque pour détruire la liche.",
			text = [=[À {link:stormwind-city}Stormwind{/link}, l'{link:archbishop-benedictus}archevêque Benedictus{/link} apprit que les hurans d'un dédale épineux des {link:the-barrens}Tarides{/link} avaient conclu un pacte avec le {link:scourge}Fléau{/link}, et qu'une liche les gouvernait. Il n'attendit pas que le mal grandisse. Il envoya des champions de la Lumière pour trancher cette union à la racine.]=],
		},
		{
			title = "Apporter la fin",
			hint = "Rapportez le crâne du Porte-froid à Undercity.",
			text = [=[Les {link:forsaken}Réprouvés{/link} ne virent d'abord aucune menace dans {link:razorfen-downs}les Souilles{/link}. Leurs rapports suivants les firent changer d'avis. {red:andrew-brownell}Andrew Brownell{/red}, des {link:royal-apothecary-society}apothicaires{/link}, croyait qu'Amnennar était lié par la pensée à {link:ner-zhul}Ner'zhul{/link} lui-même, et que ce lien devait être tranché. Il demanda le crâne de la liche.]=],
		},
	},
	mentions = {
		{ text = "Une armée du mal, les rangs croissants des Souilles" },
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "un ennemi de tout ce qu'il bâtit" },
		{ id = "mordresh-fire-eye", name = "Mordresh Fire Eye", note = "son serviteur" },
		{ id = "glutton", name = "Glutton", note = "son serviteur" },
		{ id = "ambassador-malcin", name = "Ambassadeur Malcin", note = "un autre serviteur du roi-liche" },
	},
})

Translate("frFR", "tuten-kash", {
	title = "Tuten'kash",
	subtitle = "Le démon des cryptes qui attend",
	found = "La salle du gong, Souilles de Tranchebauge",
	hint = [=[Faites sonner le grand gong des Souilles, et voyez ce qui répond.]=],
	allegiance = "Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[Tuten'kash est un démon des cryptes du {link:scourge}Fléau{/link}, l'un de ces grands êtres-araignées que le roi-liche a relevés d'entre les morts. Il se cache dans un repaire de toiles au plus profond des {link:razorfen-downs}Souilles de Tranchebauge{/link}. On dit qu'il est aveugle, et que ses fils fins lui signalent chaque pas fait près de lui. Un grand gong pend dans la salle devant son repaire. Quand il retentit, des démons plus petits viennent d'abord, puis de plus grands, et enfin Tuten'kash lui-même.]=],
		},
		{
			title = "Importance",
			text = [=[Tuten'kash est le signe que le {link:scourge}Fléau{/link} a envoyé de l'autre côté de la mer plus que des os et la peste. Les êtres-araignées du Grand Nord attendent désormais sous les épines des {link:the-barrens}Tarides{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il garde les profondeurs des Souilles avec ses démons des tombes et ses saccageurs.]=],
		},
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar le Porte-froid", note = "son maître dans les Souilles" },
	},
})

Translate("frFR", "mordresh-fire-eye", {
	title = "Mordresh Fire Eye",
	subtitle = "Le chaman mort",
	found = "Le Tas d'ossements, Souilles de Tranchebauge",
	hint = [=[Cherchez le squelette qui danse sur le monticule d'ossements.]=],
	allegiance = "Fléau",
	aliases = { "Mordresh" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mordresh Fire Eye est un lanceur de sorts squelette du {link:scourge}Fléau{/link} qui se tient sur un monticule de crânes dans {link:razorfen-downs}les Souilles{/link} de Tranchebauge, dansant parmi ses frères d'os. On dit qu'il fut autrefois un chaman {link:orcs}orc{/link}, envoyé d'{link:orgrimmar}Orgrimmar{/link} pour découvrir ce qui s'agitait dans les Souilles. Il fut tué, et le seigneur des Souilles le releva. Désormais, il brûle les vivants par le feu et pousse les morts inférieurs à la fureur. Il se vante auprès des siens qu'ils asserviront les hurans et se répandront dans les {link:the-barrens}Tarides{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Si le récit de son passé est vrai, Mordresh est la première perte de la {link:horde}Horde{/link} face au {link:scourge}Fléau{/link} en {link:kalimdor}Kalimdor{/link}.]=],
		},
		{ title = "Hauts faits", text = "• Il mène les squelettes du Tas d'ossements." },
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar le Porte-froid", note = "le seigneur qui le releva" },
	},
})

Translate("frFR", "glutton", {
	title = "Glutton",
	subtitle = "L'abomination des Souilles",
	found = [=[Les sentiers inférieurs de la Spirale d'épines, Souilles de Tranchebauge]=],
	hint = [=[Méfiez-vous du géant recousu qui erre sur le bas de la spirale d'épines.]=],
	allegiance = "Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[Glutton est une abomination, une masse de chair cousue façonnée par les nécromanciens du {link:scourge}Fléau{/link}. Il erre sur les sentiers inférieurs de la Spirale d'épines et sa faim n'a pas de fin. On dit qu'il se nourrit des morts en décomposition des Souilles, sangliers comme hurans, et qu'un nuage de maladie s'élève de la charogne dans son ventre. Plus il combat, plus il devient affamé et féroce.]=],
		},
		{
			title = "Importance",
			text = [=[Glutton est le genre d'horreur que le {link:scourge}Fléau{/link} apporta en {link:lordaeron}Lordaeron{/link}, désormais lâchée parmi les hurans.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il parcourt la Spirale d'épines pour le compte de son maître.]=],
		},
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar le Porte-froid", note = "son maître" },
	},
})

Translate("frFR", "plaguemaw-the-rotting", {
	title = "Plaguemaw le Pourrissant",
	subtitle = "Défenseur de l'idole",
	found = [=[L'idole près de l'entrée des Souilles de Tranchebauge, pendant le rituel de Belnistrasz]=],
	hint = [=[Restez auprès de Belnistrasz devant l'idole jusqu'à la toute fin.]=],
	allegiance = "Tête de mort · Fléau",
	aliases = { "Plaguemaw" },
	sections = {
		{
			title = "Résumé",
			text = [=[Plaguemaw le Pourrissant est un {link:quilboar}huran{/link} mort-vivant de la {link:death-s-head}Tête de mort{/link}, une masse de chair pourrie et de peste. Il n'attendait dans aucune salle des Souilles. Il ne sortit de l'ombre que lorsque {link:belnistrasz}Belnistrasz{/link} commença son rituel pour sceller l'idole des hurans, et il vint pour l'arrêter. Sa puanteur affaiblit le bras le plus fort, et son contact rend le corps malade et vide l'esprit.]=],
		},
		{
			title = "Importance",
			text = [=[Plaguemaw montre ce que les hurans sont devenus sous la liche : leurs morts ne sont plus honorés, mais relevés.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il combattit pour sauver l'idole des hurans du rituel de {link:belnistrasz}Belnistrasz{/link}.]=],
		},
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "l'ennemi qu'il vint arrêter" },
	},
})

Translate("frFR", "ragglesnout", {
	title = "Ragglesnout",
	subtitle = "Prêtre de la Tête de mort",
	found = [=[La Spirale d'épines, Souilles de Tranchebauge, visible seulement par moments]=],
	hint = [=[Guettez sur la Spirale d'épines un prêtre huran que l'on voit rarement.]=],
	allegiance = "Tête de mort",
	sections = {
		{
			title = "Résumé",
			text = [=[Ragglesnout est un {link:quilboar}huran{/link} de la {link:death-s-head}Tête de mort{/link} que l'on voit rarement, et seulement sur les sentiers de la Spirale d'épines. Il est encore vivant, et pourtant il sert la liche. Il manie la magie de l'ombre, soigne ses alliés et peut plier un esprit plus faible à sa volonté. Quand il apparaît, c'est sur les sentiers sous le sommet de la liche, non loin de l'endroit où erre {link:glutton}Glutton{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Ragglesnout montre que tous les prêtres de la {link:death-s-head}Tête de mort{/link} n'eurent pas à mourir pour servir le {link:scourge}Fléau{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il arpente la Spirale d'épines parmi les serviteurs d'{link:amnennar-the-coldbringer}Amnennar{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit sur le passé de Ragglesnout, ni sur la raison pour laquelle on le voit si rarement.]=],
		},
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar le Porte-froid", note = "le seigneur qu'il sert" },
	},
})

Translate("frFR", "henry-stern", {
	title = "Henry Stern",
	subtitle = "Cuisinier et alchimiste de Stormwind",
	found = [=[Les enclos des prisonniers, près de l'entrée des Souilles de Tranchebauge]=],
	hint = [=[Libérez le cuisinier retenu captif dans les enclos des Souilles de Tranchebauge.]=],
	allegiance = "Royaume de Stormwind",
	sections = {
		{
			title = "Résumé",
			text = [=[Henry Stern est un cuisinier et alchimiste de {link:stormwind-city}Stormwind{/link}. Il vint dans les {link:the-barrens}Tarides{/link} pour recueillir les herbes et les recettes locales pour son oncle Angus. Les hurans le capturèrent et le jetèrent dans leurs enclos. Il est certain qu'il aurait fini dans leur marmite. Une fois libéré, il reste où il est et attend que la sortie soit sûre. Il partage volontiers ce qu'il a appris des herbes des Tarides, parmi lesquelles l'épine d'or.]=],
		},
		{
			title = "Importance",
			text = [=[Henry Stern est la preuve de ce à quoi servait l'idole près de la porte. Les hurans ne prenaient pas de captifs pour en tirer une rançon.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il survécut à sa captivité dans {link:razorfen-downs}les Souilles{/link}.
• Il enseigne les recettes du thé à l'épine d'or et du sang de troll à ceux qui partagent ses métiers.]=],
		},
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "un compagnon de captivité" },
	},
})

Translate("frFR", "myriam-moonsinger", {
	title = "Myriam Moonsinger",
	subtitle = "Guetteuse des Souilles",
	found = [=[Une colline juste au sud de la porte des Souilles de Tranchebauge]=],
	hint = [=[Cherchez l'elfe de la nuit qui surveille les épines des Souilles depuis une colline au sud.]=],
	allegiance = "Elfes de la nuit",
	sections = {
		{
			title = "Résumé",
			text = [=[Myriam Moonsinger est une éclaireuse {link:night-elves}elfe de la nuit{/link} qui monte la garde sur {link:razorfen-downs}les Souilles{/link} de Tranchebauge depuis une colline près de leur porte. Son peuple a senti une obscurité venir de ce lieu et l'a envoyée découvrir ce que c'était. Ce qu'elle a trouvé la trouble. Un diplomate mort-vivant est venu chez les hurans, un maître de la magie des arcanes, et elle ne croit pas qu'il soit l'un des {link:forsaken}Réprouvés{/link}. Elle craint qu'il ne soit quelque chose de pire.]=],
		},
		{
			title = "Importance",
			text = [=[Myriam fut parmi les premiers à voir le {link:scourge}Fléau{/link} à l'œuvre dans les {link:the-barrens}Tarides{/link}. Elle vit des hurans sortir de l'ombre pour venir à l'émissaire, jour après jour, avides du pouvoir qu'il offrait.]=],
		},
	},
	chapters = {
		{
			title = "Une armée du mal",
			hint = [=[Aidez l'éclaireuse à éclaircir les rangs autour des Souilles.]=],
			text = [=[Myriam ne pouvait pas combattre seule les partisans de l'émissaire. Avec de l'aide, elle frappa les guerriers hurans, les tisse-épines et les cultistes de la {link:death-s-head}Tête de mort{/link} qui se rassemblaient près de la porte. Ce qu'elle vit la convainquit que le {link:scourge}Fléau{/link} était l'un des plus graves dangers que le monde ait jamais affrontés. Elle resta pour continuer à surveiller.]=],
		},
	},
	bonds = {
		{ id = "ambassador-malcin", name = "Ambassadeur Malcin", note = "l'émissaire qu'elle surveille" },
