Translate("frFR", "death-s-head", {
	title = "Tête de mort",
	aliases = { "tribu de la Tête de mort", "culte de la Tête de mort" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Tête de mort, ce sont les grands prêtres des {link:quilboar}hurans{/link}, gardiens des lieux de sépulture des {link:razorfen-downs}Souilles de Tranchebauge{/link}. Ils se sont tournés vers le {link:scourge}Fléau{/link}. Sous la liche {link:amnennar-the-coldbringer}Amnennar le Porte-froid{/link}, ils servent la non-mort dans le lieu le plus saint de leur peuple, et beaucoup de leurs guerriers marchent désormais comme des cadavres desséchés.]=],
		},
		{
			title = "Le marché",
			text = [=[Nul hors des Souilles ne connaît toute la vérité sur la façon dont cela commença. Le {link:scourge}Fléau{/link} envoya un émissaire, l'ambassadeur {link:ambassador-malcin}Malcin{/link}, qui offrit aux hurans les {link:the-barrens}Tarides{/link} et davantage en échange de leur aide. {link:varimathras}Varimathras{/link} croit que la vieille du {link:razorfen-kraul}Kraal de Tranchebauge{/link} se tint à l'écart de l'accord. Les prêtres des Souilles, eux, n'en firent rien. Certains membres de leur tribu sont devenus d'une force effrayante et portent les marques de la peste. L'{link:night-elves}elfe de la nuit{/link} {link:myriam-moonsinger}Myriam Moonsinger{/link} vit des hurans sortir de l'ombre chaque jour pour supplier l'émissaire de leur donner plus de pouvoir.]=],
		},
		{
			title = "L'ordre",
			text = [=[Des prêtres, des nécromanciens, des géomanciens et des cultistes de la Tête de mort servent la liche aux côtés de guerriers hurans vivants et de tisse-épines. Des hurans desséchés, des sangliers de guerre et des squelettes remplissent leurs rangs. Parmi eux se trouvent {link:ragglesnout}Ragglesnout{/link}, qui vit encore, et {link:plaguemaw-the-rotting}Plaguemaw le Pourrissant{/link}, qui ne vit plus. Leurs captifs sont gardés dans des enclos près de la porte, et ceux qui ne sont pas secourus sont brûlés et dévorés devant l'idole.]=],
		},
	},
})
